<?php $title='Correo y notificaciones'; require __DIR__.'/partials/top.php'; $cfg=[];$profiles=[]; try{$st=appDb()->prepare('SELECT * FROM correo WHERE tenant_id=? AND is_default=1 ORDER BY correo_id DESC LIMIT 1');$st->execute([$_SESSION['user']['tenant_id']]);$cfg=$st->fetch()?:[];$all=appDb()->prepare('SELECT correo_id,nombre,metodo_envio,correo,graph_user,server,is_default,estado FROM correo WHERE tenant_id=? ORDER BY is_default DESC,correo_id DESC');$all->execute([$_SESSION['user']['tenant_id']]);$profiles=$all->fetchAll();}catch(Throwable $e){} $method=$cfg['metodo_envio']??'SMTP'; $notif=['login_enabled'=>1,'message_enabled'=>1,'handoff_enabled'=>1,'critical_enabled'=>1,'cooldown_minutes'=>10]; try{$ns=appDb()->prepare('SELECT * FROM notification_runtime_settings WHERE tenant_id=?');$ns->execute([$_SESSION['user']['tenant_id']]);$notif=$ns->fetch()?:$notif;}catch(Throwable $e){} ?>
<section class="welcome"><div><small>COMUNICACIONES</small><h1>Correo y notificaciones</h1><p>Configura SMTP o Microsoft Graph. Si no lo configuras, ZYNKO funciona normalmente pero no enviará correos.</p></div></section>
